INSERT INTO "Recipes" ("Id", "Name", "Description", "Instructions", "Servings", "PreparationTimeMinutes", "CreatedAt") VALUES
(1, 'Gebna Beda ma Zeitoun', 'A simple Egyptian breakfast plate of soft white cheese served with cured olives, tomato and warm baladi bread.', 'Slice the white cheese and arrange on a plate with the olives and sliced tomato. Drizzle with a little oil and serve with warm baladi bread.', 2, 10, '2026-07-31 00:00:00+00'),
(2, 'Zabady bel Asal wal Mekasarat', 'Creamy yogurt drizzled with honey and topped with toasted nuts, a favourite Egyptian breakfast or light dessert.', 'Spoon the yogurt into bowls. Drizzle generously with honey and scatter over the toasted walnuts and almonds. Serve immediately.', 4, 10, '2026-07-31 00:00:00+00'),
(3, 'Ful Nabet bel Salata', 'Sprouted fava beans tossed with tomato, onion and herbs for a light, protein-rich salad popular in Egyptian homes.', 'Boil the sprouted fava beans briefly until just tender, then cool. Toss with diced tomato, onion, parsley and lemon juice, and season with salt and cumin.', 4, 25, '2026-07-31 00:00:00+00'),
(4, 'Basterma Mashwia', 'Thin slices of spiced cured beef basterma pan-seared until fragrant, a bold Egyptian appetizer.', 'Heat a dry pan and sear the basterma slices briefly on each side until fragrant and lightly crisped. Serve hot with lemon wedges and bread.', 3, 10, '2026-07-31 00:00:00+00'),
(5, 'Homos Sham Mohammas', 'Crunchy roasted chickpeas seasoned with cumin and salt, a popular Egyptian street snack.', 'Toss the boiled chickpeas with oil, cumin and salt. Roast in a hot oven, stirring occasionally, until dry and crisp. Cool before serving.', 4, 40, '2026-07-31 00:00:00+00'),
(6, 'Aish Baladi Homemade', 'Egypt''s everyday whole-wheat flatbread, baked hot and fast until it puffs into a pocket.', 'Mix the flours, yeast and salt with warm water to form a soft dough and let it rise until doubled. Divide into rounds, rest briefly, then bake in a very hot oven until puffed and lightly browned.', 6, 90, '2026-07-31 00:00:00+00'),
(7, 'Semit Masri', 'Crisp Egyptian bread rings coated in sesame seeds, a favourite street snack sold from carts across Cairo.', 'Knead the flour, yeast, sugar and salt with water into a smooth dough and let rise. Shape into rings, coat generously in sesame seeds, and bake until golden and crisp.', 8, 100, '2026-07-31 00:00:00+00'),
(8, 'Fiteer bel Gebna wal Basterma', 'Flaky layered Egyptian pastry folded with white cheese and spiced basterma, baked until golden.', 'Roll and stretch the dough into thin layers, brushing with butter between folds. Scatter white cheese and basterma slices over half, fold over, and bake until golden and crisp.', 4, 60, '2026-07-31 00:00:00+00'),
(9, 'Shorbet Kishk', 'A warming Upper Egyptian soup made from fermented wheat and yoghurt kishk, simmered with chicken stock.', 'Whisk the kishk into warm chicken stock until smooth. Simmer gently, stirring often, until thickened. Season with salt and serve hot with a drizzle of ghee.', 4, 30, '2026-07-31 00:00:00+00'),
(10, 'Kishk bel Samna', 'A thick Upper Egyptian breakfast porridge of fermented kishk cooked in ghee until rich and creamy.', 'Melt the ghee in a pot and stir in the kishk with a little milk to form a thick paste. Cook gently over low heat, stirring constantly, until smooth and creamy. Serve warm.', 3, 20, '2026-07-31 00:00:00+00'),
(11, 'Shorbet Sha''ria', 'A light, comforting soup of toasted vermicelli noodles simmered in chicken broth.', 'Toast the noodles in a little butter until golden. Pour in the chicken stock and simmer until the noodles are tender. Season with salt and pepper before serving.', 4, 20, '2026-07-31 00:00:00+00'),
(12, 'Shorbet Samak', 'A fragrant Egyptian coastal fish soup simmered with tomato, celery and warming spices.', 'Sauté the onion, garlic and celery in oil until soft. Add the tomatoes and cook briefly, then pour in water and bring to a boil. Add the fish pieces and simmer gently until cooked through. Season with cumin and salt.', 4, 40, '2026-07-31 00:00:00+00'),
(13, 'Shorbet Hamam', 'A traditional restorative pigeon broth, long simmered with warming spices and prized for new mothers.', 'Simmer the pigeon in water with the onion until the meat is very tender and the broth is richly flavoured. Strain, season with cinnamon, cumin and salt, and serve the broth hot with the pigeon meat.', 2, 90, '2026-07-31 00:00:00+00'),
(14, 'Salatet Tahina Sada', 'A simple, tangy tahini sauce whisked with garlic and lemon, served alongside grilled meats and fish.', 'Whisk the tahini with cold water until smooth. Stir in crushed garlic, lemon juice and salt until the sauce is creamy and pourable.', 4, 10, '2026-07-31 00:00:00+00'),
(15, 'Salsa Toum', 'A pungent Egyptian garlic sauce whipped with oil and lemon, traditionally served with grilled chicken.', 'Crush the garlic to a fine paste with salt. Gradually whisk in the oil and lemon juice until the sauce turns thick and white.', 6, 15, '2026-07-31 00:00:00+00'),
(16, 'Salatet Zabadi bel Toum', 'Cool, garlicky yoghurt sauce often spooned over grilled meats or stuffed vegetables.', 'Stir the crushed garlic and salt into the yoghurt until well combined. Chill briefly before serving.', 4, 10, '2026-07-31 00:00:00+00'),
(17, 'Dukkah Masri', 'An iconic Egyptian blend of toasted nuts, sesame and spices, eaten by dipping bread in oil then dukkah.', 'Toast the hazelnuts, sesame seeds, coriander seeds and cumin separately until fragrant. Cool, then grind coarsely together with salt. Serve alongside bread and olive oil for dipping.', 6, 20, '2026-07-31 00:00:00+00'),
(18, 'Ful Akhdar bel Lahma', 'Tender fresh green fava beans simmered with beef in a garlicky coriander-scented sauce, a springtime favourite.', 'Brown the beef with onion and garlic. Add the fresh green fava beans and a little water, cover, and simmer until the beans and meat are tender. Finish with chopped coriander leaves.', 4, 55, '2026-07-31 00:00:00+00'),
(19, 'Loubia Khadra bel Lahma', 'Fresh cowpeas stewed with beef in a light tomato broth, a seasonal home-style favourite.', 'Brown the beef with onion and garlic. Add tomatoes and simmer briefly into a sauce. Stir in the fresh cowpeas, cover with water, and simmer gently until the peas and meat are tender.', 4, 60, '2026-07-31 00:00:00+00'),
(20, 'Qolqas bel Lahma', 'Hearty colocasia root stewed with beef and coriander in a garlicky broth, an Egyptian winter classic.', 'Brown the beef with onion and garlic. Add the peeled colocasia chunks and cover with water, then simmer until the colocasia is tender and creamy. Finish with chopped coriander leaves and a squeeze of lemon.', 4, 65, '2026-07-31 00:00:00+00'),
(21, 'Habb Al-Aziz Muhamas', 'Roasted chufa tubers, a chewy, nutty Egyptian snack sold by street vendors.', 'Rinse the chufa tubers and roast in a dry pan or oven, stirring often, until lightly toasted and fragrant. Serve warm with a light sprinkle of salt.', 4, 20, '2026-07-31 00:00:00+00'),
(22, 'Fasolia Khadra bel Lahma', 'Green beans simmered slowly with beef in a garlicky tomato sauce until meltingly tender.', 'Brown the beef with onion and garlic. Add tomatoes and simmer into a sauce. Stir in the green beans and cook gently, covered, until the beans and beef are tender.', 4, 55, '2026-07-31 00:00:00+00'),
(23, 'Bazella bel Lahma', 'Sweet green peas and carrots stewed with beef in a light tomato sauce, a classic Egyptian family dinner.', 'Brown the beef with onion. Add diced carrots and tomatoes and simmer briefly. Stir in the peas and a little water, cover, and simmer until everything is tender.', 4, 50, '2026-07-31 00:00:00+00'),
(24, 'Sabanekh bel Lahma', 'Silky spinach stewed with beef and garlic, served over rice as a nourishing Egyptian dinner.', 'Brown the beef with onion and garlic. Add the chopped spinach and a little water, cover, and simmer until the spinach has wilted down and the beef is tender.', 4, 50, '2026-07-31 00:00:00+00'),
(25, 'Salatet Sabanekh', 'A bright, lemony salad of blanched spinach tossed with garlic and olive oil.', 'Blanch the spinach briefly, then drain well and chop. Toss with crushed garlic, lemon juice, oil and salt while still warm.', 4, 15, '2026-07-31 00:00:00+00'),
(26, 'Silq bel Lahma', 'Swiss chard stewed with beef and tomato, a hearty vegetable dinner found across Egyptian households.', 'Brown the beef with onion and garlic. Add tomatoes and simmer briefly. Stir in the chopped chard, cover, and simmer until the chard is tender and the sauce has thickened.', 4, 55, '2026-07-31 00:00:00+00'),
(27, 'Kousa bel Lahma', 'Diced zucchini simmered with beef in a garlicky tomato sauce, lighter than its stuffed cousin.', 'Brown the beef with onion and garlic. Add tomatoes and simmer into a sauce. Stir in the diced squash and simmer gently until tender.', 4, 50, '2026-07-31 00:00:00+00'),
(28, 'Batates bel Lahma', 'Cubed potatoes simmered with beef in a rich tomato sauce, a comforting everyday Egyptian stew.', 'Brown the beef with onion and garlic. Add tomatoes and simmer briefly. Stir in the potato cubes, cover with water, and simmer until the potatoes are tender.', 4, 55, '2026-07-31 00:00:00+00'),
(29, 'Torshi Betengan', 'Small eggplants cured in a tangy salt brine with garlic, an Egyptian pickle jar staple.', 'Slit the eggplants and pack with crushed garlic. Layer into a jar and cover with a salted water brine and lemon juice. Seal and leave at room temperature for several days until tangy.', 8, 20, '2026-07-31 00:00:00+00'),
(30, 'Torshi Malfouf', 'Crunchy pickled cabbage wedges, a bright and tangy accompaniment to grilled meats.', 'Cut the cabbage into wedges and pack into a jar with garlic. Cover with a salted water brine, seal, and leave to cure for several days until sour and crisp.', 8, 15, '2026-07-31 00:00:00+00'),
(31, 'Torshi Left', 'Egypt''s iconic pink pickled turnips, coloured naturally by beetroot and always served alongside taamia and ful.', 'Cut the turnips into wedges and pack into a jar with sliced beetroot for colour. Cover with a salted water brine, seal, and leave to cure for about a week until bright pink and tangy.', 8, 15, '2026-07-31 00:00:00+00'),
(32, 'Torshi Gazar', 'Crunchy pickled carrot sticks, mildly spiced and cured in brine.', 'Cut the carrots into sticks and pack into a jar with garlic. Cover with a salted water brine, seal, and leave to cure for several days until tangy and crisp.', 8, 15, '2026-07-31 00:00:00+00'),
(33, 'Torshi Khiar', 'Crisp pickled cucumbers cured in brine with garlic, a refreshing everyday pickle.', 'Pack the whole small cucumbers into a jar with garlic. Cover with a salted water brine, seal, and leave at room temperature until sour and crisp.', 8, 15, '2026-07-31 00:00:00+00'),
(34, 'Torshi Basal', 'Tangy pickled baby onions, a sharp little side dish for rich meat dishes.', 'Peel small onions and pack into a jar. Cover with a salted water brine and a squeeze of lemon, seal, and leave to cure for several days until soft and tangy.', 6, 15, '2026-07-31 00:00:00+00'),
(35, 'Torshi Filfil', 'Tangy pickled peppers cured in brine, a colourful addition to any Egyptian pickle plate.', 'Slice the peppers into strips and pack into a jar with garlic. Cover with a salted water brine, seal, and leave to cure for several days until tangy.', 8, 15, '2026-07-31 00:00:00+00'),
(36, 'Salatet Betengan Mashwi', 'Smoky roasted eggplant mashed with garlic, tomato and lemon, an Egyptian mezze without tahini.', 'Roast the eggplants over an open flame or under a grill until the skin blackens and the flesh softens. Peel and mash the flesh, then mix with crushed garlic, diced tomato, lemon juice and oil.', 4, 40, '2026-07-31 00:00:00+00'),
(37, 'Salatet Loubia', 'A cold, garlicky salad of cooked black-eyed peas tossed with tomato and lemon.', 'Boil the cowpeas until tender, then cool. Toss with diced tomato, onion, crushed garlic, lemon juice and oil.', 4, 45, '2026-07-31 00:00:00+00'),
(38, 'Salatet Fasolia Beida', 'A hearty salad of cooked white beans dressed with garlic, lemon and fresh parsley.', 'Combine the cooked white kidney beans with chopped parsley, crushed garlic, lemon juice and oil, and season with salt.', 4, 20, '2026-07-31 00:00:00+00'),
(39, 'Salatet Batates', 'A creamy Egyptian potato salad tossed with egg, mayonnaise and a light dressing, a popular side at gatherings.', 'Boil the potatoes until tender, then cool and dice. Toss with chopped boiled egg and mayonnaise, and season with lemon juice, salt and pepper.', 4, 40, '2026-07-31 00:00:00+00'),
(40, 'Salatet Bengar', 'Roasted beetroot tossed with garlic and yoghurt, a colourful Egyptian mezze.', 'Boil or roast the beetroots until tender, then peel and dice. Toss with crushed garlic, yoghurt and a little lemon juice, and season with salt.', 4, 45, '2026-07-31 00:00:00+00'),
(41, 'Salatet Filfil Mashwi', 'Sweet roasted peppers peeled and dressed with garlic, oil and bright lemon.', 'Roast the peppers until the skins blister and blacken, then peel and slice. Toss with crushed garlic, lemon juice and oil, and season with salt.', 4, 30, '2026-07-31 00:00:00+00'),
(42, 'Salatet Karnabeet', 'Boiled cauliflower florets tossed with garlic, lemon and parsley for a light Egyptian side salad.', 'Boil the cauliflower florets until just tender, then cool. Toss with crushed garlic, chopped parsley, lemon juice and oil, and season with salt.', 4, 25, '2026-07-31 00:00:00+00'),
(43, 'Karnabeet Meqli bel Tahina', 'Golden fried cauliflower florets served with a creamy garlic tahini sauce, a beloved Egyptian side dish.', 'Deep-fry the cauliflower florets until golden and crisp. Whisk the tahini with garlic and lemon juice until smooth. Serve the fried cauliflower drizzled with the tahini sauce.', 4, 35, '2026-07-31 00:00:00+00'),
(44, 'Mahshi Koussa bi Roz', 'Hollowed zucchini stuffed with a herbed rice filling and simmered gently, a vegetarian classic.', 'Hollow out the zucchini. Mix rice with diced tomato, parsley, dill and oil, and stuff into the zucchini. Arrange in a pot, cover with water and lemon juice, and simmer until the rice and zucchini are tender.', 4, 60, '2026-07-31 00:00:00+00'),
(45, 'Mahshi Betengan bi Roz', 'Small eggplants hollowed and stuffed with herbed rice, simmered in a light lemony broth.', 'Hollow out the eggplants. Mix rice with diced tomato, parsley and dill, and stuff into the eggplants. Simmer gently in a pot with water and lemon juice until the rice and eggplant are tender.', 4, 60, '2026-07-31 00:00:00+00'),
(46, 'Mahshi Filfil bi Roz', 'Green peppers stuffed with a herbed vegetarian rice filling, gently braised in tomato sauce.', 'Hollow out the peppers. Mix rice with diced tomato, parsley and dill, and stuff into the peppers. Simmer in a pot with tomato sauce and water until the peppers and rice are tender.', 4, 55, '2026-07-31 00:00:00+00'),
(47, 'Mahshi Tamatem', 'Ripe tomatoes hollowed out and stuffed with herbed rice, baked until soft and fragrant.', 'Slice the tops off the tomatoes and scoop out the flesh, reserving it. Mix rice with the reserved tomato flesh, parsley, dill and oil, and stuff back into the tomatoes. Bake in a covered dish with a little water until the rice is tender.', 4, 55, '2026-07-31 00:00:00+00'),
(48, 'Mahshi Basal', 'Whole onions hollowed and layered, stuffed with a spiced rice filling, a lesser-known Egyptian mahshi.', 'Parboil the onions until the layers separate easily, then fill each layer with a mixture of rice, tomato and herbs. Arrange snugly in a pot, cover with water, and simmer until the rice is tender.', 4, 65, '2026-07-31 00:00:00+00'),
(49, 'Mahshi Silq bi Roz', 'Swiss chard leaves rolled around a herbed rice filling, simmered gently like grape leaves.', 'Blanch the chard leaves until pliable. Mix rice with diced tomato, parsley and dill, roll into the leaves, and simmer in a pot with water and lemon juice until the rice is tender.', 4, 65, '2026-07-31 00:00:00+00'),
(50, 'Filfil Mahshi bel Freekeh', 'Green peppers stuffed with smoky freekeh grains and beef, an Upper Egyptian twist on the classic mahshi.', 'Hollow out the peppers. Cook the freekeh partially, then mix with minced beef, onion and tomatoes, and stuff into the peppers. Simmer in a pot with tomato sauce until the peppers are tender and the freekeh is cooked through.', 4, 70, '2026-07-31 00:00:00+00'),
(51, 'Ardi Shawki Mahshi bel Lahma', 'Artichoke bottoms stuffed with spiced minced beef, braised gently until tender.', 'Trim the artichokes down to their bottoms. Mix minced beef with onion, garlic and parsley, and press into the artichoke bottoms. Braise in a pot with water and lemon juice until the artichokes are tender.', 4, 70, '2026-07-31 00:00:00+00'),
(52, 'Ardi Shawki bel Zeit wal Limon', 'Tender artichoke bottoms braised gently in olive oil, garlic and lemon, served cold as a mezze.', 'Trim the artichokes to their bottoms and simmer gently in water with lemon juice until tender. Drain and dress with oil, crushed garlic and a little more lemon juice. Chill before serving.', 4, 45, '2026-07-31 00:00:00+00'),
(53, 'Dawood Basha', 'Egyptian meatballs simmered in a rich tomato and onion sauce with pine nuts, a beloved home-style classic.', 'Shape the minced beef with onion and pine nuts into small balls and brown them in a pan. Add tomatoes and a little water, and simmer gently until the sauce thickens and the meatballs are cooked through.', 4, 45, '2026-07-31 00:00:00+00'),
(54, 'Kofta bel Batates', 'A beloved Egyptian tray bake of spiced beef kofta layered with potato slices in tomato sauce.', 'Shape the minced beef with onion and parsley into fingers. Layer sliced potatoes and kofta in a baking tray, cover with a light tomato sauce, and bake until the potatoes are tender and the kofta is cooked through.', 5, 60, '2026-07-31 00:00:00+00'),
(55, 'Kofta Halla', 'Beef kofta simmered slowly in a clay pot with tomato sauce, an Alexandrian home-style favourite.', 'Shape the minced beef with onion and parsley into small fingers and brown lightly. Add tomatoes and a little water, cover, and simmer slowly in the pot until the sauce thickens and the kofta is tender.', 4, 55, '2026-07-31 00:00:00+00'),
(56, 'Kammounia bel Lahma', 'A fragrant Cairene beef stew built on a deeply spiced cumin and garlic sauce.', 'Brown the beef cubes with onion and garlic. Stir in plenty of cumin and a little tomato, cover with water, and simmer slowly until the beef is very tender and the sauce is thick and aromatic.', 4, 90, '2026-07-31 00:00:00+00'),
(57, 'Kubeba Maqliya', 'Torpedo-shaped bulgur shells stuffed with spiced minced beef and deep-fried until crisp.', 'Soak the bulgur, then grind with a little beef into a smooth shell paste. Cook the remaining minced beef with onion and pine nuts for the filling. Shape the bulgur paste around the filling into torpedoes and deep-fry until golden and crisp.', 4, 75, '2026-07-31 00:00:00+00'),
(58, 'Fatta bel Aranib', 'A festive variation of Egypt''s classic fatta, layering crisp bread and rice under tender braised rabbit.', 'Braise the rabbit until very tender, reserving the broth. Toast bread pieces until crisp and layer in a dish with cooked rice. Ladle over the hot broth and top with the braised rabbit and fried garlic.', 4, 90, '2026-07-31 00:00:00+00'),
(59, 'Firakh bel Furn', 'Whole chicken roasted with potatoes and garlic until golden, a beloved Friday family lunch.', 'Rub the chicken with garlic, oil and spices. Arrange with potato wedges in a roasting tray and roast until the chicken is golden and cooked through and the potatoes are tender.', 4, 90, '2026-07-31 00:00:00+00'),
(60, 'Fattet Firakh', 'Layers of crisp bread and rice topped with tender shredded chicken and garlicky broth.', 'Toast bread pieces until crisp and layer in a dish with cooked rice. Ladle over hot chicken broth, top with shredded boiled chicken, and finish with fried garlic and a squeeze of lemon.', 4, 60, '2026-07-31 00:00:00+00'),
(61, 'Fattet Gambari', 'A coastal variation of Egypt''s classic fatta, layering crisp bread and rice under garlicky shrimp.', 'Toast bread pieces until crisp and layer in a dish with cooked rice. Sauté the shrimp with garlic until pink, and arrange over the rice. Finish with a drizzle of oil and fried garlic before serving.', 4, 45, '2026-07-31 00:00:00+00'),
(62, 'Kalawi Mashwiya', 'Grilled beef kidneys marinated in garlic, cumin and lemon, a favourite Egyptian offal skewer.', 'Clean and slice the kidneys, then marinate in garlic, cumin, oil and lemon juice. Thread onto skewers and grill over high heat until just cooked through.', 4, 35, '2026-07-31 00:00:00+00'),
(63, 'Kibda Mashwia', 'Simple grilled beef liver skewers, lightly seasoned and cooked quickly over high heat.', 'Cut the liver into cubes and marinate briefly with garlic, oil and cumin. Thread onto skewers and grill quickly over high heat until just cooked through, taking care not to overcook.', 4, 25, '2026-07-31 00:00:00+00'),
(64, 'Lisan Mashwi', 'Grilled slices of tender braised beef tongue, finished with garlic and lemon.', 'Simmer the tongue until tender, then peel and slice. Marinate briefly in garlic, oil and lemon, then grill quickly on both sides until lightly charred.', 4, 120, '2026-07-31 00:00:00+00'),
(65, 'Lisan Salata', 'A cold salad of thinly sliced boiled beef tongue tossed with parsley, onion and lemon.', 'Slice the boiled tongue thinly. Toss with finely chopped onion, parsley, lemon juice and oil, and season with salt and pepper.', 4, 20, '2026-07-31 00:00:00+00'),
(66, 'Tehal Eskandarani', 'Alexandria''s famous grilled spleen sandwich, spiced with cumin and garlic and stuffed into fresh bread.', 'Slice the spleen thinly and marinate with garlic, cumin and oil. Grill quickly over very high heat until just cooked. Stuff into warm shami bread with a squeeze of lemon.', 4, 30, '2026-07-31 00:00:00+00'),
(67, 'Deek Rumi bel Furn', 'A whole turkey roasted slowly with garlic and warming spices, a festive Egyptian centerpiece.', 'Rub the turkey with garlic, oil, cinnamon and salt. Roast slowly in a covered tray, basting occasionally, until deeply golden and cooked through.', 8, 150, '2026-07-31 00:00:00+00'),
(68, 'Hamam Mahshi Freekeh', 'Whole pigeon stuffed with smoky freekeh grains and roasted until deeply golden, a specialty of Upper Egypt.', 'Partially cook the freekeh with butter and onion, then stuff loosely into the cleaned pigeons. Truss and roast or pan-sear until the skin is golden and the freekeh is fully cooked.', 2, 80, '2026-07-31 00:00:00+00'),
(69, 'Molokhia bel Gambari', 'A coastal variation of Egypt''s beloved green soup, made with shrimp instead of poultry.', 'Cook the shrimp briefly in a light broth and set aside. Fry garlic and coriander seeds in butter until fragrant, stir into the broth, then add the chopped molokhia leaves and simmer briefly. Return the shrimp just before serving, over rice.', 4, 45, '2026-07-31 00:00:00+00'),
(70, 'Molokhia Yabsa bel Thoum', 'A simple vegetarian version of molokhia made with dried jute leaves and a fragrant garlic-coriander tasha.', 'Rehydrate the dried molokhia leaves in a little broth. Fry garlic and coriander seeds in butter until fragrant, then stir into the molokhia and simmer briefly. Serve hot over rice.', 4, 30, '2026-07-31 00:00:00+00'),
(71, 'Sayadeya Gambari', 'Golden spiced rice topped with garlicky sautéed shrimp, the coastal cousin of fish sayadeya.', 'Fry sliced onions until deeply caramelized, then use most of them to flavour the broth the rice is cooked in. Sauté the shrimp with garlic and cumin, and serve over the rice topped with the remaining fried onions.', 4, 55, '2026-07-31 00:00:00+00'),
(72, 'Samak Eskandarani', 'Alexandria-style whole fried fish served with rice and a garlicky tahini sauce.', 'Score and deep-fry the whole fish until crisp and golden. Serve with steamed rice and a bowl of garlic tahini sauce for drizzling.', 4, 40, '2026-07-31 00:00:00+00'),
(73, 'Ankaleesh Mashwi', 'Grilled eel basted with garlic, cumin and lemon, a Nile Delta specialty.', 'Clean and gut the eel, then score the skin. Marinate in garlic, cumin, oil and lemon juice, then grill over hot coals, turning often, until the skin is crisp and the flesh is cooked through.', 4, 40, '2026-07-31 00:00:00+00'),
(74, 'Renga Salad', 'A cold salad of smoked herring flaked with onion, tomato and lemon, a traditional coastal appetizer.', 'Flake the smoked herring, removing any bones. Toss with finely chopped onion, diced tomato, lemon juice and oil.', 4, 20, '2026-07-31 00:00:00+00'),
(75, 'Renga Mashwia', 'Whole smoked herring warmed briefly over a grill and served with fresh bread and lemon.', 'Warm the smoked herring briefly over a hot grill until heated through and lightly crisped at the edges. Serve with lemon wedges and warm bread.', 4, 15, '2026-07-31 00:00:00+00'),
(76, 'Sardin Mekhalel', 'Salted sardines marinated cold with garlic, lemon and oil, a punchy coastal appetizer.', 'Soak the salted sardines briefly to reduce saltiness, then pat dry. Marinate with crushed garlic, lemon juice and oil for a few hours before serving chilled.', 4, 30, '2026-07-31 00:00:00+00'),
(77, 'Bream Mashwi', 'Whole bream marinated in garlic, cumin and lemon, then grilled until smoky and tender.', 'Score the bream and marinate with garlic, cumin, oil and lemon juice. Grill over hot coals, turning once, until the skin is crisp and the flesh flakes easily.', 4, 35, '2026-07-31 00:00:00+00'),
(78, 'Kaboria bel Salsa', 'Fresh crab simmered in a garlicky tomato sauce, a coastal Egyptian favourite.', 'Sauté onion and garlic in oil until soft. Add tomatoes and simmer into a sauce. Add the crab pieces and simmer gently until the crab is cooked through and the sauce has thickened.', 4, 40, '2026-07-31 00:00:00+00'),
(79, 'Gambari bel Thoum', 'Plump shrimp quickly sautéed in garlic butter, a simple and fragrant coastal appetizer.', 'Melt the butter with garlic in a hot pan. Add the shrimp and sauté quickly until pink and just cooked through. Finish with a squeeze of lemon and chopped parsley.', 4, 20, '2026-07-31 00:00:00+00'),
(80, 'Roz Muammar', 'Upper Egyptian baked creamy rice, slow-cooked in milk until golden on top, traditionally served with roasted meats.', 'Parboil the rice briefly, then transfer to a baking dish with milk, butter and sugar. Bake slowly, uncovered, until the top turns golden and the rice is creamy underneath.', 4, 90, '2026-07-31 00:00:00+00'),
(81, 'Roz bel Foul Akhdar', 'Fluffy rice cooked together with fresh green fava beans and dill, a bright seasonal side dish.', 'Sauté the fava beans briefly in butter with dill. Add the rinsed rice and stock, bring to a boil, then cover and simmer until the rice is tender and the liquid absorbed.', 4, 35, '2026-07-31 00:00:00+00'),
(82, 'Roz bel Lahma', 'A simple everyday one-pot rice cooked with tender beef chunks, a staple weeknight dinner.', 'Brown the beef with onion in a pot. Add the rinsed rice and stock, bring to a boil, then cover and simmer until the rice is tender and the beef is cooked through.', 4, 55, '2026-07-31 00:00:00+00'),
(83, 'Ruz bel Loubia', 'A simple pilaf of rice and black-eyed peas cooked together, a humble one-pot Egyptian side.', 'Sauté the onion in oil until soft. Add the rinsed rice and cooked cowpeas, cover with water, and simmer until the rice is tender and the liquid is absorbed.', 4, 40, '2026-07-31 00:00:00+00'),
(84, 'Macarona bel Zeit', 'An Alexandrian-style pasta tossed in olive oil with tomato and fresh dill, lighter than the baked bechamel versions.', 'Cook the macaroni until al dente. Sauté garlic in oil, add diced tomatoes and dill, and simmer briefly into a light sauce. Toss through the drained pasta and serve warm.', 4, 30, '2026-07-31 00:00:00+00'),
(85, 'Macarona bel Gambari', 'A coastal seafood pasta tossed with garlicky shrimp in a light tomato sauce.', 'Cook the macaroni until al dente. Sauté the shrimp with garlic in oil until pink, add tomatoes, and simmer briefly. Toss through the drained pasta and finish with chopped parsley.', 4, 35, '2026-07-31 00:00:00+00'),
(86, 'Sabanekh bel Gambari', 'A coastal take on spinach stew, simmered with shrimp instead of meat.', 'Sauté onion and garlic in oil. Add the chopped spinach and a little water, and simmer until wilted. Stir in the shrimp and cook briefly until just pink and cooked through.', 4, 40, '2026-07-31 00:00:00+00'),
(87, 'Amar El Din', 'A silky sweet apricot drink cooked from dried apricots, a Ramadan favourite for breaking the fast.', 'Simmer the dried apricots in water with sugar until completely soft. Blend until smooth, then dilute with a little more water and chill before serving cold.', 4, 30, '2026-07-31 00:00:00+00'),
(88, 'Tamarhindi', 'A tangy-sweet tamarind drink, a refreshing Ramadan classic served ice-cold.', 'Soak the tamarind pulp in hot water until softened, then mash and strain to extract the juice. Sweeten with sugar and chill before serving over ice.', 4, 25, '2026-07-31 00:00:00+00'),
(89, 'Sobia', 'A creamy chilled coconut and rice milk drink, a beloved Ramadan refreshment.', 'Blend soaked rice with coconut and milk until smooth, then strain. Sweeten with sugar and a touch of cardamom, and chill thoroughly before serving.', 4, 40, '2026-07-31 00:00:00+00'),
(90, 'Ganzabil', 'A warming spiced ginger drink, sipped hot on cool Egyptian evenings.', 'Simmer fresh ginger in water until fragrant and slightly golden. Strain and sweeten with sugar, then serve hot with a pinch of cinnamon.', 4, 20, '2026-07-31 00:00:00+00'),
(91, 'Asir Asab bel Limon', 'Fresh sugarcane juice brightened with a splash of lime, Egypt''s favourite roadside refresher.', 'Pour the sugarcane juice over ice. Stir in fresh lime juice and a few mint leaves, and serve immediately.', 4, 10, '2026-07-31 00:00:00+00'),
(92, 'Khoshaf Ramadan', 'A jewelled compote of dried fruits and nuts soaked overnight, Egypt''s essential Ramadan dessert.', 'Soak the dried apricots, raisins, dried figs and prunes in water overnight until plump. Sweeten lightly with sugar and scatter over toasted almonds and pine nuts before serving chilled.', 6, 20, '2026-07-31 00:00:00+00'),
(93, 'Basbousa bel Gozz Hindi', 'A moist semolina cake soaked in syrup and studded with shredded coconut, a coconut twist on Egypt''s favourite dessert.', 'Mix semolina with sugar, melted butter, yoghurt and shredded coconut into a batter. Spread in a tray and bake until golden. Pour warm sugar syrup over the hot cake and let it soak in before serving.', 8, 55, '2026-07-31 00:00:00+00'),
(94, 'Qatayef Asafiri', 'Small stuffed pancakes filled with sweetened whipping cream, a beloved Ramadan dessert.', 'Cook small rounds of batter on a griddle until set on the bottom but still soft on top. Pinch closed around a filling of sweetened whipping cream, and dust with crushed pistachios before serving.', 6, 60, '2026-07-31 00:00:00+00'),
(95, 'Kahk bel Gozz', 'Buttery Eid cookies filled with crushed walnuts, dusted generously with powdered sugar.', 'Rub butter into flour until sandy, then bring together with a little milk into a soft dough. Wrap portions around a spoonful of sweetened crushed walnuts, shape into rounds, and bake until pale golden. Dust generously with sugar once cool.', 10, 70, '2026-07-31 00:00:00+00'),
(96, 'Mishmoshiya', 'A silky apricot dessert made from dried apricot paste, chilled and topped with cream and nuts.', 'Simmer the dried apricots with sugar and water until very soft, then blend into a smooth paste. Chill in bowls and top with whipped cream and toasted almonds before serving.', 4, 30, '2026-07-31 00:00:00+00'),
(97, 'Loz Msakar', 'Sugar-glazed almonds, a festive Egyptian treat handed out at weddings and celebrations.', 'Toast the almonds lightly. Melt sugar with a splash of water and cardamom into a syrup, add the almonds, and stir constantly until the sugar crystallizes into a crisp coating.', 8, 25, '2026-07-31 00:00:00+00'),
(98, 'Fool Sudani Muhammas', 'Simple roasted salted peanuts, a favourite everyday Egyptian snack.', 'Roast the peanuts in a dry pan or oven, stirring often, until fragrant and lightly golden. Toss with oil and salt while still warm.', 6, 15, '2026-07-31 00:00:00+00'),
(99, 'Mekasarat Muhamasa', 'A mixed platter of roasted nuts and seeds, lightly salted, served at gatherings and celebrations.', 'Toast the almonds, hazelnuts and pumpkin seeds together in a dry pan until golden and fragrant. Toss with salt while warm and cool before serving.', 8, 20, '2026-07-31 00:00:00+00'),
(100, 'Balah Mahshi bel Mekasarat', 'Plump dates stuffed with toasted nuts, a simple festive Ramadan sweet.', 'Slit each date open and remove the pit. Stuff with a toasted walnut or almond half and press closed. Arrange on a plate to serve.', 6, 20, '2026-07-31 00:00:00+00'),
(101, 'Koshari', 'Egypt''s national dish made of rice, macaroni, and lentils, topped with tomato sauce.', 'Boil rice, macaroni, lentils, and chickpeas. Make a tomato sauce with garlic and cumin. Serve layered.', 4, 45, '2026-07-31 00:00:00+00'),
(102, 'Molokhia', 'A traditional Egyptian green soup made from finely chopped Jew''s Mallow.', 'Simmer the finely chopped leaves in chicken stock. Fry garlic and coriander in ghee (taqliya) and stir into the soup.', 4, 30, '2026-07-31 00:00:00+00'),
(103, 'Mahshi Waraq Enab', 'Stuffed grape leaves rolled with a fragrant rice and herb mixture.', 'Mix rice, tomatoes, herbs, and onions. Roll inside grape leaves and simmer until tender.', 6, 60, '2026-07-31 00:00:00+00'),
(104, 'Ful Medames', 'Slow-cooked fava beans, a staple Egyptian breakfast.', 'Simmer broad beans slowly. Mash lightly with oil, cumin, salt, and lemon.', 4, 120, '2026-07-31 00:00:00+00'),
(105, 'Taameya', 'Egyptian falafel made from crushed fava beans and fresh herbs.', 'Blend beans with herbs, onions, and garlic. Shape into patties and deep fry.', 4, 45, '2026-07-31 00:00:00+00'),
(106, 'Macarona Bechamel', 'Baked macaroni layered with spiced minced meat and creamy bechamel sauce.', 'Boil macaroni. Cook beef with onions. Make bechamel with flour, milk, and ghee. Layer and bake until golden.', 8, 60, '2026-07-31 00:00:00+00'),
(107, 'Om Ali', 'Traditional Egyptian bread pudding with nuts and cream.', 'Layer pastry with nuts and raisins. Pour hot sweetened milk over it and top with cream. Bake until golden.', 6, 30, '2026-07-31 00:00:00+00'),
(108, 'Moussaka Masreya', 'Fried eggplant layered with spiced beef and tomato sauce.', 'Fry eggplant slices. Cook minced beef with onions and tomatoes. Layer and bake.', 6, 50, '2026-07-31 00:00:00+00'),
(109, 'Roz Bel Laban', 'Creamy Egyptian rice pudding.', 'Simmer rice in full cream milk and sugar until tender and thickened. Top with nuts or cream.', 4, 45, '2026-07-31 00:00:00+00'),
(110, 'Sayadeya', 'Coastal Egyptian fish with caramelized onion rice.', 'Fry fish. Caramelize onions deeply, add water and cumin, then cook the rice in this dark broth.', 4, 60, '2026-07-31 00:00:00+00'),
(111, 'Kofta Mashweya', 'Grilled spiced minced beef skewers.', 'Mix minced beef with grated onion, parsley, salt, and pepper. Shape onto skewers and grill.', 4, 30, '2026-07-31 00:00:00+00'),
(112, 'Fatteh Masreya', 'A celebratory dish of crispy bread, rice, beef, and a garlicky tomato-vinegar sauce.', 'Layer toasted bread and cooked rice. Top with boiled beef chunks and a sauce made of garlic, tomato, and vinegar.', 6, 90, '2026-07-31 00:00:00+00'),
(113, 'Shorbet Adss', 'Warm and comforting Egyptian yellow lentil soup.', 'Boil lentils with onions, carrots, and tomatoes. Blend until smooth. Add cumin and serve hot.', 4, 35, '2026-07-31 00:00:00+00'),
(114, 'Shakshouka Masreya', 'Eggs cooked in a chunky tomato, onion, and pepper sauce.', 'Sauté onions and peppers, add tomatoes. Crack eggs into the sauce and cook until set.', 2, 20, '2026-07-31 00:00:00+00'),
(115, 'Kabab Halla', 'Tender beef cubes slow-cooked with melting onions.', 'Brown beef cubes in ghee. Add sliced onions and spices, cook slowly until tender.', 4, 90, '2026-07-31 00:00:00+00'),
(116, 'Tagen Bamia Bel Lahma', 'Okra and beef stew baked in a clay pot.', 'Brown beef, add onions, garlic, and tomatoes. Add okra and bake in a tagen (clay pot) until tender.', 5, 75, '2026-07-31 00:00:00+00'),
(117, 'Salatat Baladi', 'Classic Egyptian mixed salad.', 'Chop tomatoes, cucumbers, onions, and parsley. Dress with lemon juice and salt.', 4, 10, '2026-07-31 00:00:00+00'),
(118, 'Baid Bel Basterma', 'Eggs scrambled with Egyptian cured beef pastrami.', 'Sauté basterma in ghee, then add eggs and scramble until just set.', 2, 10, '2026-07-31 00:00:00+00'),
(119, 'Hawawshi', 'Crispy baladi bread stuffed with spiced minced meat.', 'Mix minced beef with onions, peppers, and spices. Stuff into baladi bread and bake until crispy.', 4, 40, '2026-07-31 00:00:00+00'),
(120, 'Kebda Iskandarani', 'Alexandrian-style stir-fried liver with garlic and peppers.', 'Quickly stir-fry liver with garlic, cumin, and peppers. Serve hot with lemon.', 3, 15, '2026-07-31 00:00:00+00')
ON CONFLICT ("Name") DO NOTHING;

